class Solution {
public:
    vector<string> largestString(vector<int>& nums) {
        vector<string> ans;
        for (int x : nums) {
            string s;
            for (int b = 25; b >= 0; --b) {
                int weight = 1 << b;
                int count = x / weight;
                s.append(count, char('a' + b));
                x %= weight;
            }
            ans.push_back(s);
        }
        return ans;
    }
};
